	OpenedEditor editor = Graphite::SolutionEditor::Open(file);
	REQUIRE(editor.HasValue());
	REQUIRE(editor.GetValue()->AddFolder("Engine/Tests").HasValue());
	REQUIRE(editor.GetValue()->RenameFolder("Engine", "Core").HasValue());
	REQUIRE(editor.GetValue()->Save().HasValue());

	const std::string written = ReadWholeFile(file);

	CHECK(written.find("<Folder Name=\"/Core/\"") != std::string::npos);
	CHECK(written.find("<Folder Name=\"/Core/Tests/\"") != std::string::npos);
	CHECK(written.find("/Engine/") == std::string::npos);
